{"action":"write_file","path":"pool.test.js","content":"'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { pool } = require('./pool');

test('results are in input order', async () => {
  const out = await pool([30, 10, 20], async (ms, i) => { await new Promise((r) => setTimeout(r, ms)); return i; }, 2);
  assert.deepEqual(out, [0, 1, 2]);
});

test('an empty list', async () => {
  assert.deepEqual(await pool([], async () => 1, 3), []);
});

test('validation: items not an array', async () => {
  await assert.rejects(
    async () => await pool(null, () => {}, 1),
    TypeError
  );
});

test('validation: worker not a function', async () => {
  await assert.rejects(
    async () => await pool([], 'not a function', 1),
    TypeError
  );
});

test('validation: limit not a positive integer', async () => {
  await assert.rejects(
    async () => await pool([], () => {}, 0),
    RangeError
  );
  await assert.rejects(
    async () => await pool([], () => {}, -1),
    RangeError
  );
  await assert.rejects(
    async () => await pool([], () => {}, 1.5),
    RangeError
  );
  await assert.rejects(
    async () => await pool([], () => {}, '2'),
    RangeError
  );
});

test('sync throw in arguments makes returned promise reject immediately', async () => {
  // pool is async function so it never throws synchronously, but returns a rejected promise
  const p = pool(null, () => {}, 1);
  assert.ok(p instanceof Promise);
  await assert.rejects(p, TypeError);
});

test('worker error rejects immediately and stops starting jobs', async () => {
  let started = 0;
  const items = [1, 2, 3, 4, 5];
  const promise = pool(items, async (item, i) => {
    started++;
    if (item === 2) {
      throw new Error('fail');
    }
    await new Promise((r) => setTimeout(r, 50));
    return item;
  }, 2);

  await assert.rejects(promise, { message: 'fail' });
  // Since limit is 2, items 1 and 2 start. Item 2 fails. No further items (3, 4, 5) should start.
  assert.equal(started, 2);
});

test('limit larger than items starts all at once', async () => {
  let active = 0;
  let maxActive = 0;
  const items = [1, 2, 3, 4];
  await pool(items, async () => {
    active++;
    maxActive = Math.max(maxActive, active);
    await new Promise((r) => setTimeout(r, 10));
    active--;
  }, 10);

  assert.equal(maxActive, 4);
});
"}
